#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

_WIZARD_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$_WIZARD_DIR/.." && pwd)
cd "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/apps/web/.env.local"
WEB_DIR="$REPO_ROOT/apps/web"

github_app_new_url() {
  local lab="$1" name="$2" owner="$3"
  python3 - "$lab" "$name" "$owner" <<'PY'
import sys
from urllib.parse import urlencode

lab, name, owner = sys.argv[1], sys.argv[2], sys.argv[3]
lab = lab.rstrip("/")
params = [
    ("name", name),
    ("url", lab),
    ("callback_urls[]", f"{lab}/api/auth/callback/github"),
    ("public", "true"),
    ("webhook_active", "true"),
    ("webhook_url", f"{lab}/api/github-webhook"),
    ("administration", "write"),
    ("contents", "write"),
    ("workflows", "write"),
    ("actions", "write"),
    ("issues", "write"),
    ("pull_requests", "write"),
    ("emails", "read"),
    ("events[]", "pull_request"),
    ("events[]", "issue_comment"),
    ("events[]", "pull_request_review_comment"),
]
base = "https://github.com/settings/apps/new"
if owner:
    base = f"https://github.com/organizations/{owner}/settings/apps/new"
print(f"{base}?{urlencode(params)}", end="")
PY
}

pem_file_to_env_line() {
  python3 - "$1" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1]).expanduser()
text = path.read_text().strip().replace("\r\n", "\n")
if "BEGIN" not in text or "PRIVATE KEY" not in text:
    sys.stderr.write("not a PEM file\n")
    sys.exit(1)
print(text.replace("\n", "\\n"), end="")
PY
}

env_unescape_nl() {
  python3 -c 'import sys; print(sys.stdin.read().replace("\\n", "\n"), end="")'
}

minify_json_line() {
  python3 -c 'import json,sys; json.dump(json.load(sys.stdin), sys.stdout, separators=(",", ":"))'
}

unprefix_assignment() {
  local key="$1" value="$2"
  while [[ "$value" == "$key="* ]]; do
    value="${value#"$key="}"
  done
  printf '%s' "$value"
}

put_wrangler_secret() {
  local name="$1" value="$2"
  value=$(unprefix_assignment "$name" "$value")
  if [[ -z "$value" ]]; then
    note "skipping $name (empty in $ENV_FILE)"
    return 0
  fi
  if (
    cd "$WEB_DIR"
    printf '%s' "$value" | bunx wrangler secret put "$name"
  ); then
    printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  SKIPPED+=("Worker secret $name")
  warn "wrangler secret put $name failed"
}

github_apps_list_url() {
  if [[ -n "${GITHUB_APP_OWNER:-}" ]]; then
    printf '%s' "https://github.com/organizations/${GITHUB_APP_OWNER}/settings/apps"
  else
    printf '%s' "https://github.com/settings/apps"
  fi
}

github_app_settings_url() {
  if [[ -z "${HOSTED_APP_SLUG:-}" ]]; then
    github_apps_list_url
    return
  fi
  if [[ -n "${GITHUB_APP_OWNER:-}" ]]; then
    printf '%s' "https://github.com/organizations/${GITHUB_APP_OWNER}/settings/apps/${HOSTED_APP_SLUG}"
  else
    printf '%s' "https://github.com/settings/apps/${HOSTED_APP_SLUG}"
  fi
}

ingest_antigravity_json() {
  local src="$1" json
  if [[ -z "$src" || ! -f "$src" ]]; then
    return 1
  fi
  if ! json=$(minify_json_line < "$src"); then
    warn "file is not JSON"
    return 1
  fi
  write_env CATALOG_ANTIGRAVITY_OAUTH "$json"
}

github_app_form_steps() {
  local lab="${VITE_LAB_URL%/}"
  step "Homepage URL: ${lab}"
  step "Callback URL: ${lab}/api/auth/callback/github"
  step "Webhook URL: ${lab}/api/github-webhook"
  step "Webhook secret: paste the value from the previous stage."
  step "Repository permissions Read and write: Administration, Contents, Workflows, Actions, Issues, Pull requests."
  step "Subscribe to events: pull_request, issue_comment, pull_request_review_comment."
  step "Leave Request user authorization (OAuth) during installation unticked."
  step "Leave Enable Device Flow unticked."
  step "Account permissions: Email addresses Read-only."
  step "Organization permissions: all No access."
  step "Where can this GitHub App be installed: Any account."
  step "Create GitHub App."
}

generate_hex() {
  openssl rand -hex 32
}

ensure_wrangler_login() {
  if ( cd "$WEB_DIR" && bunx wrangler whoami >/dev/null 2>&1 ); then
    return 0
  fi
  say "wrangler needs a Cloudflare login. A browser window will open."
  ( cd "$WEB_DIR" && bunx wrangler login ) || warn "wrangler login failed"
}

ask_required() {
  local key="$1" prompt="$2" mode="${3:-ask}"
  while true; do
    if [[ "$mode" == secret ]]; then
      ask_secret "$key" "$prompt"
    else
      ask "$key" "$prompt"
    fi
    if [[ -n "${!key}" ]]; then
      write_env "$key" "${!key}"
      return 0
    fi
    warn "$key is required to boot Lab"
    if confirm "Continue with $key blank?"; then
      return 0
    fi
  done
}

patch_wrangler_vars() {
  python3 - "$WEB_DIR/wrangler.jsonc" \
    "$(_existing HOSTED_APP_CLIENT_ID || true)" \
    "$(_existing HOSTED_APP_SLUG || true)" \
    "$(_existing VITE_ACTION_REF || true)" \
    "$(_existing VITE_LAB_URL || true)" \
    "$(_existing VITE_SOURCE_REPO_URL || true)" <<'PY'
import json
import pathlib
import re
import sys

path = pathlib.Path(sys.argv[1])
pairs = {
    "HOSTED_APP_CLIENT_ID": sys.argv[2],
    "HOSTED_APP_SLUG": sys.argv[3],
    "VITE_ACTION_REF": sys.argv[4],
    "VITE_LAB_URL": sys.argv[5],
    "VITE_SOURCE_REPO_URL": sys.argv[6],
}
text = path.read_text()
for key, value in pairs.items():
    if not value:
        continue
    escaped = json.dumps(value)[1:-1]
    text, n = re.subn(
        rf'("{key}":\s*")(?:\\.|[^"\\])*(")',
        lambda m, escaped=escaped: m.group(1) + escaped + m.group(2),
        text,
        count=1,
    )
    if n != 1:
        sys.stderr.write(f"did not replace {key}\n")
        sys.exit(1)
path.write_text(text)
PY
}

patch_wrangler_after() {
  local marker="$1" key="$2" value="$3"
  python3 - "$WEB_DIR/wrangler.jsonc" "$marker" "$key" "$value" <<'PY'
import json
import pathlib
import re
import sys

path = pathlib.Path(sys.argv[1])
marker, key, value = sys.argv[2], sys.argv[3], sys.argv[4]
text = path.read_text()
idx = text.find(marker)
if idx < 0:
    sys.stderr.write(f"missing {marker}\n")
    sys.exit(1)
head, tail = text[:idx], text[idx:]
escaped = json.dumps(value)[1:-1]
tail, n = re.subn(
    rf'("{key}":\s*")(?:\\.|[^"\\])*(")',
    lambda m, escaped=escaped: m.group(1) + escaped + m.group(2),
    tail,
    count=1,
)
if n != 1:
    sys.stderr.write(f"did not replace {key} after {marker}\n")
    sys.exit(1)
path.write_text(head + tail)
PY
}

d1_uuid_from_text() {
  python3 -c "$(cat <<'PY'
import json
import re
import sys

text = sys.stdin.read()
try:
    data = json.loads(text)
    for key in ("uuid", "database_id", "id"):
        if isinstance(data, dict) and data.get(key):
            print(data[key], end="")
            raise SystemExit(0)
except json.JSONDecodeError:
    pass
m = re.search(r'"database_id":\s*"([0-9a-f-]{36})"', text)
if not m:
    m = re.search(
        r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
        text,
        re.I,
    )
if m:
    print(m.group(1) if m.lastindex else m.group(0), end="")
    raise SystemExit(0)
sys.exit(1)
PY
)"
}

d1_id_from_list() {
  local name="$1"
  python3 -c "$(cat <<'PY'
import json
import sys

name = sys.argv[1]
raw = sys.stdin.read()
try:
    data = json.loads(raw)
except json.JSONDecodeError:
    sys.exit(1)
rows = data if isinstance(data, list) else data.get("result") or []
for row in rows:
    if row.get("name") != name:
        continue
    ident = row.get("uuid") or row.get("database_id") or row.get("id")
    if ident:
        print(ident, end="")
        raise SystemExit(0)
sys.exit(1)
PY
)" "$name"
}

