TOTAL_STAGES=22

banner "hakasebot Lab setup"

# ── 1. Public URLs ───────────────────────────────────────────────────────
stage "Public Lab URLs"
say "Writes apps/web/.env.local. CI has no secrets.*, so this wizard never runs gh secret set."
if [[ ! -f "$ENV_FILE" ]]; then
  cp "$WEB_DIR/.env.example" "$ENV_FILE"
  note "copied apps/web/.env.example → $ENV_FILE"
fi
ask VITE_LAB_URL "Public Lab origin (local default http://localhost:47821):"
ask VITE_SOURCE_REPO_URL "Source repo URL:"
ask VITE_ACTION_REF "Action ref (owner/repo@ref):"
write_env VITE_LAB_URL "$VITE_LAB_URL"
write_env VITE_SOURCE_REPO_URL "$VITE_SOURCE_REPO_URL"
write_env VITE_ACTION_REF "$VITE_ACTION_REF"
if [[ "$VITE_LAB_URL" == *localhost* || "$VITE_LAB_URL" == *127.0.0.1* || "$VITE_LAB_URL" == *::1* ]]; then
  warn "GitHub will not deliver webhooks to loopback. Sign-in callback still works locally."
fi

# ── 2. better-auth ────────────────────────────────────────────────────────
stage "BETTER_AUTH_SECRET"
say "better-auth seals session cookies with this. Rotating it signs everyone out."
if [[ -n "$(_existing BETTER_AUTH_SECRET || true)" ]]; then
  if confirm "Rotate BETTER_AUTH_SECRET?"; then
    BETTER_AUTH_SECRET=$(bunx --bun @better-auth/cli secret | tail -n1 | tr -d '\r')
  else
    BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET)
    note "keeping the existing secret"
  fi
else
  say "Generating one with bunx --bun @better-auth/cli secret."
  BETTER_AUTH_SECRET=$(bunx --bun @better-auth/cli secret | tail -n1 | tr -d '\r')
fi
BETTER_AUTH_SECRET=$(unprefix_assignment BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET")
write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"

# ── 3. Webhook HMAC ───────────────────────────────────────────────────────
stage "HOSTED_APP_WEBHOOK_SECRET"
say "GitHub cannot put this in the prefill URL. We generate it here, then you paste it on the App form."
if [[ -n "$(_existing HOSTED_APP_WEBHOOK_SECRET || true)" ]]; then
  if confirm "Rotate HOSTED_APP_WEBHOOK_SECRET?"; then
    HOSTED_APP_WEBHOOK_SECRET=$(generate_hex)
  else
    HOSTED_APP_WEBHOOK_SECRET=$(_existing HOSTED_APP_WEBHOOK_SECRET)
    note "keeping the existing webhook secret"
  fi
else
  HOSTED_APP_WEBHOOK_SECRET=$(generate_hex)
fi
write_env HOSTED_APP_WEBHOOK_SECRET "$HOSTED_APP_WEBHOOK_SECRET"
say "Paste this into GitHub's Webhook secret field on the next stage:"
printf '  %s%s%s\n' "$BOLD" "$HOSTED_APP_WEBHOOK_SECRET" "$RESET"
pause "Copied the webhook secret?"

# ── 4. Create Hosted bot App ────────────────────────────────────────────
stage "Create the Hosted bot App"
say "One Hosted bot App is Lab sign-in and the Bot. GitHub's form still lives under Developer settings → GitHub Apps."
ask GITHUB_APP_NAME "App name on GitHub (becomes the slug):"
ask GITHUB_APP_OWNER "Owner org slug (empty = your personal account):"
if confirm "Register a new Hosted bot App now?"; then
  if command -v python3 >/dev/null 2>&1; then
    APP_NEW_URL=$(github_app_new_url "$VITE_LAB_URL" "$GITHUB_APP_NAME" "$GITHUB_APP_OWNER")
  else
    warn "python3 missing; opening a blank New GitHub App form. Fill the steps below by hand."
    APP_NEW_URL="$(github_apps_list_url)/new"
  fi
  open_url "$APP_NEW_URL"
  github_app_form_steps
  pause "Created the App?"
else
  ask HOSTED_APP_SLUG "Existing App slug (github.com/apps/<slug>):"
  write_env HOSTED_APP_SLUG "$HOSTED_APP_SLUG"
  open_url "$(github_app_settings_url)"
  step "Webhook secret: paste the value from the previous stage if this App does not already have one, then Save."
  pause "Webhook secret saved on the existing App, or already set?"
fi

# ── 6. Client ID + slug ────────────────────────────────────────────────
stage "Client ID and slug"
say "Client ID is public (JWT iss). The slug is the last path segment of https://github.com/apps/<slug>. Slug can stay blank until the bot is needed."
open_url "$(github_apps_list_url)"
step "Copy the slug from the public page URL, github.com/apps/<slug>. Enter keeps it blank."
ask HOSTED_APP_SLUG "Paste the App slug:"
write_env HOSTED_APP_SLUG "$HOSTED_APP_SLUG"
open_url "$(github_app_settings_url)"
step "Copy Client ID from About."
ask_required HOSTED_APP_CLIENT_ID "Paste the Client ID:"

# ── 6. Client secret ────────────────────────────────────────────────────
stage "Client secret"
say "This is the OAuth Client secret, not the PEM. Generate a new one; GitHub shows it once. Lab will not boot without it."
open_url "$(github_app_settings_url)"
step "Client secrets → Generate a new client secret → copy it."
ask_required HOSTED_APP_CLIENT_SECRET "Paste the Client secret:" secret

# ── 8. PEM ──────────────────────────────────────────────────────────────
stage "Private key PEM"
say "HOSTED_APP_PRIVATE_KEY must be the downloaded PEM, not the Client secret. Stored as a single .env line with \\n. Lab sign-in boots without it; the bot needs it."
if confirm "Store a private key now?"; then
  open_url "$(github_app_settings_url)"
  step "Private keys → Generate a private key. A .pem file downloads."
  ask PEM_PATH "Path to the downloaded .pem file:"
  PEM_FILE="${PEM_PATH/#\~/$HOME}"
  if [[ -z "$PEM_PATH" || ! -f "$PEM_FILE" ]]; then
    warn "no file at that path; PEM left unset"
  elif HOSTED_APP_PRIVATE_KEY=$(pem_file_to_env_line "$PEM_FILE"); then
    write_env HOSTED_APP_PRIVATE_KEY "$HOSTED_APP_PRIVATE_KEY"
  else
    warn "could not read a PEM from that file; left unset"
  fi
else
  note "skipped"
fi

# ── 8. Host console ───────────────────────────────────────────────────────
stage "HOST_CONSOLE_TOKEN"
say "/host is 404 until this is set. Generate a long random token; paste it in the browser later."
if [[ -n "$(_existing HOST_CONSOLE_TOKEN || true)" ]]; then
  if confirm "Rotate HOST_CONSOLE_TOKEN?"; then
    HOST_CONSOLE_TOKEN=$(generate_hex)
  else
    HOST_CONSOLE_TOKEN=$(_existing HOST_CONSOLE_TOKEN)
    note "keeping the existing token"
  fi
else
  if confirm "Generate HOST_CONSOLE_TOKEN now?"; then
    HOST_CONSOLE_TOKEN=$(generate_hex)
  else
    HOST_CONSOLE_TOKEN=""
  fi
fi
if [[ -n "$HOST_CONSOLE_TOKEN" ]]; then
  write_env HOST_CONSOLE_TOKEN "$HOST_CONSOLE_TOKEN"
else
  note "left unset"
fi

# ── 9. LAB_DEV_USER ──────────────────────────────────────────────────────
stage "LAB_DEV_USER"
say "On loopback, LAB_DEV_USER=1 treats the User as signed in (ADR-0012). Never put this on the Worker."
write_env LAB_DEV_USER "1"
note "wrote LAB_DEV_USER=1"

# ── 10. Dev PAT ─────────────────────────────────────────────────────────
stage "LAB_DEV_GITHUB_TOKEN"
say "Optional. GitHub writes from Lab still need a PAT with repo and workflow. Do not reuse a Cloud Agent gh token."
if confirm "Set LAB_DEV_GITHUB_TOKEN now?"; then
  open_url "https://github.com/settings/tokens/new?scopes=repo,workflow&description=hakasebot-lab-dev"
  step "Classic token. Leave repo and workflow ticked. Generate token. Copy it once."
  ask_secret LAB_DEV_GITHUB_TOKEN "Paste the PAT:"
  write_env LAB_DEV_GITHUB_TOKEN "$LAB_DEV_GITHUB_TOKEN"
else
  note "skipped"
fi

# ── 11. Catalog Anthropic ─────────────────────────────────────────────
stage "Catalog: Anthropic"
say "Optional. Missing catalog keys make that engine's picker fail; custom-string still works."
if confirm "Set CATALOG_ANTHROPIC_API_KEY now?"; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Create Key → copy it."
  ask_secret CATALOG_ANTHROPIC_API_KEY "Paste the Anthropic key:"
  write_env CATALOG_ANTHROPIC_API_KEY "$CATALOG_ANTHROPIC_API_KEY"
else
  note "skipped"
fi

# ── 12. Catalog OpenAI ─────────────────────────────────────────────────
stage "Catalog: OpenAI"
if confirm "Set CATALOG_OPENAI_API_KEY now?"; then
  open_url "https://platform.openai.com/api-keys"
  step "Create new secret key → copy it."
  ask_secret CATALOG_OPENAI_API_KEY "Paste the OpenAI key:"
  write_env CATALOG_OPENAI_API_KEY "$CATALOG_OPENAI_API_KEY"
else
  note "skipped"
fi

# ── 13. Catalog xAI ─────────────────────────────────────────────────────
stage "Catalog: xAI"
say "Listing needs prepaid team credits but does not spend them. Restrict the key so it cannot chat."
if confirm "Set CATALOG_XAI_API_KEY now?"; then
  open_url "https://console.x.ai"
  step "API Keys → Create API Key."
  step "Chat models only, Models endpoint only, 1 token per minute."
  ask_secret CATALOG_XAI_API_KEY "Paste the xAI key:"
  write_env CATALOG_XAI_API_KEY "$CATALOG_XAI_API_KEY"
else
  note "skipped"
fi

# ── 14. Catalog Cursor ──────────────────────────────────────────────────
stage "Catalog: Cursor"
say "User API key from the Cursor dashboard. hakasebot maps it to CURSOR_API_KEY at spawn."
if confirm "Set CATALOG_CURSOR_API_KEY now?"; then
  open_url "https://cursor.com/dashboard/api"
  step "User API Keys → create a key → copy the secret from the dialog (shown once)."
  ask_secret CATALOG_CURSOR_API_KEY "Paste the Cursor user API key:"
  write_env CATALOG_CURSOR_API_KEY "$CATALOG_CURSOR_API_KEY"
else
  note "skipped"
fi

# ── 15. Catalog Antigravity ─────────────────────────────────────────────
stage "Catalog: Antigravity"
say "CATALOG_ANTIGRAVITY_OAUTH is the agy OAuth JSON from the OS keyring (service=gemini, username=antigravity). secret-tool fails on KDE; python libsecret dump works."
if confirm "Set CATALOG_ANTIGRAVITY_OAUTH now?"; then
  CATALOG_ANTIGRAVITY_OAUTH=""
  if confirm "Try dumping the keyring with python3 now?"; then
    if CATALOG_ANTIGRAVITY_OAUTH=$(
      python3 - <<'PY'
import gi
gi.require_version("Secret", "1")
from gi.repository import Secret
s = Secret.Service.get_sync(Secret.ServiceFlags.OPEN_SESSION, None)
i = s.search_sync(
    None,
    {"service": "gemini", "username": "antigravity"},
    Secret.SearchFlags.UNLOCK | Secret.SearchFlags.LOAD_SECRETS,
    None,
)[0]
print(i.get_secret().get().decode(), end="")
PY
    ) && CATALOG_ANTIGRAVITY_OAUTH=$(printf '%s' "$CATALOG_ANTIGRAVITY_OAUTH" | minify_json_line); then
      write_env CATALOG_ANTIGRAVITY_OAUTH "$CATALOG_ANTIGRAVITY_OAUTH"
    else
      warn "keyring dump failed"
      CATALOG_ANTIGRAVITY_OAUTH=""
    fi
  fi
  if [[ -z "$CATALOG_ANTIGRAVITY_OAUTH" ]]; then
    ask_secret CATALOG_ANTIGRAVITY_OAUTH "Paste the OAuth JSON (one line), or Enter to use a file:"
    if [[ -n "$CATALOG_ANTIGRAVITY_OAUTH" ]]; then
      if CATALOG_ANTIGRAVITY_OAUTH=$(printf '%s' "$CATALOG_ANTIGRAVITY_OAUTH" | minify_json_line); then
        write_env CATALOG_ANTIGRAVITY_OAUTH "$CATALOG_ANTIGRAVITY_OAUTH"
      else
        warn "paste was not JSON"
        CATALOG_ANTIGRAVITY_OAUTH=""
      fi
    fi
  fi
  if [[ -z "$CATALOG_ANTIGRAVITY_OAUTH" ]]; then
    ask ANTIGRAVITY_JSON_PATH "Path to the OAuth JSON file:"
    ingest_antigravity_json "${ANTIGRAVITY_JSON_PATH/#\~/$HOME}" || note "left unset"
  fi
else
  note "skipped"
fi

# ── 16. Worker public vars ─────────────────────────────────────────────
stage "Cloudflare Worker public vars"
say "These stay wrangler.jsonc vars, not secrets."
note "HOSTED_APP_CLIENT_ID=$(_existing HOSTED_APP_CLIENT_ID || true)"
note "HOSTED_APP_SLUG=$(_existing HOSTED_APP_SLUG || true)"
note "VITE_ACTION_REF=$(_existing VITE_ACTION_REF || true)"
note "VITE_LAB_URL=$(_existing VITE_LAB_URL || true)"
note "VITE_SOURCE_REPO_URL=$(_existing VITE_SOURCE_REPO_URL || true)"
warn "bun run build inlines VITE_* from .env.local. A localhost VITE_LAB_URL will bake into the client bundle."
if confirm "Write those five keys into apps/web/wrangler.jsonc vars now?"; then
  if patch_wrangler_vars; then
    printf '  %s✓ wrote%s wrangler.jsonc vars\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("wrangler.jsonc vars")
    warn "could not patch wrangler.jsonc"
  fi
fi
if confirm "Delete Worker secret HOSTED_APP_CLIENT_ID if it exists, so the wrangler.jsonc var wins?"; then
  ensure_wrangler_login
  ( cd "$WEB_DIR" && bunx wrangler secret delete HOSTED_APP_CLIENT_ID ) || note "nothing to delete, or delete failed"
fi

# ── 17. D1 ──────────────────────────────────────────────────────────────
stage "Cloudflare D1"
say "D1 holds vault, repo, and wake rows. Binding is DB, database name hakasebot. Lookup is by name on this account, not the committed database_id."
if confirm "Bind D1 hakasebot in wrangler.jsonc?"; then
  ensure_wrangler_login
  D1_ID=""
  if D1_LIST=$( cd "$WEB_DIR" && bunx wrangler d1 list --json 2>/dev/null ); then
    D1_ID=$(printf '%s' "$D1_LIST" | d1_id_from_list hakasebot) || D1_ID=""
    [[ -n "$D1_ID" ]] && note "found existing D1 hakasebot"
  fi
  if [[ -z "$D1_ID" ]]; then
    if confirm "No D1 named hakasebot on this account. Create it?"; then
      if D1_OUT=$( cd "$WEB_DIR" && bunx wrangler d1 create hakasebot ); then
        printf '%s\n' "$D1_OUT"
        D1_ID=$(printf '%s' "$D1_OUT" | d1_uuid_from_text) || D1_ID=""
      fi
    fi
  fi
  if [[ -n "$D1_ID" ]] && patch_wrangler_after '"d1_databases"' database_id "$D1_ID"; then
    printf '  %s✓ wrote%s database_id %s\n' "$GREEN" "$RESET" "$D1_ID"
  else
    SKIPPED+=("D1 hakasebot")
    warn "could not bind D1 hakasebot"
  fi
else
  note "skipped"
fi

# ── 18. KV ──────────────────────────────────────────────────────────────
stage "Cloudflare KV"
say "KV holds the Model catalog cache. Binding is MODEL_CATALOG. Lookup is by title on this account."
if confirm "Bind KV MODEL_CATALOG in wrangler.jsonc?"; then
  ensure_wrangler_login
  KV_ID=""
  if KV_LIST=$( cd "$WEB_DIR" && bunx wrangler kv namespace list 2>/dev/null ); then
    KV_ID=$(printf '%s' "$KV_LIST" | kv_id_from_list MODEL_CATALOG) || KV_ID=""
    [[ -n "$KV_ID" ]] && note "found existing KV MODEL_CATALOG"
  fi
  if [[ -z "$KV_ID" ]]; then
    if confirm "No KV titled MODEL_CATALOG on this account. Create it?"; then
      if KV_OUT=$( cd "$WEB_DIR" && bunx wrangler kv namespace create MODEL_CATALOG ); then
        printf '%s\n' "$KV_OUT"
        KV_ID=$(printf '%s' "$KV_OUT" | kv_id_from_text) || KV_ID=""
      fi
    fi
  fi
  if [[ -n "$KV_ID" ]] && patch_wrangler_after '"kv_namespaces"' id "$KV_ID"; then
    printf '  %s✓ wrote%s MODEL_CATALOG id %s\n' "$GREEN" "$RESET" "$KV_ID"
  else
    SKIPPED+=("KV MODEL_CATALOG")
    warn "could not bind KV MODEL_CATALOG"
  fi
else
  note "skipped"
fi

# ── 19. Custom domain ─────────────────────────────────────────────────
stage "Cloudflare custom domain"
LAB_HOST=$(lab_hostname "$(_existing VITE_LAB_URL || true)")
ROUTE_PATTERN=$(wrangler_routes_pattern || true)
say "Wrangler deploy creates the Custom Domain DNS record. The hostname must already be a zone on this Cloudflare account, with no leftover CNAME."
if is_loopback_host "$LAB_HOST"; then
  note "VITE_LAB_URL is loopback. Not writing a custom domain. Disabling wrangler.jsonc routes so deploy cannot attach ${ROUTE_PATTERN:-the committed hostname}."
  if patch_routes_enabled false; then
    printf '  %s✓ wrote%s routes enabled false\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("disable custom domain")
    warn "could not disable routes; refuse deploy later"
  fi
else
  note "hostname: $LAB_HOST"
  open_url "https://dash.cloudflare.com"
  step "Add this hostname as a site if it is not already a zone. Wait until the zone is Active."
  step "If a CNAME already exists for ${LAB_HOST}, delete it."
  pause "Zone is Active and the hostname is free of a CNAME?"
  if confirm "Write ${LAB_HOST} into wrangler.jsonc routes as a custom domain?"; then
    if patch_wrangler_after '"routes"' pattern "$LAB_HOST" && patch_routes_enabled true; then
      printf '  %s✓ wrote%s routes pattern %s enabled true\n' "$GREEN" "$RESET" "$LAB_HOST"
    else
      SKIPPED+=("custom domain $LAB_HOST")
      warn "could not patch routes"
    fi
  fi
fi

# ── 20. Deploy ────────────────────────────────────────────────────────
stage "Deploy Worker"
say "bun run deploy is bun run build && wrangler deploy. That publishes the Worker, binds D1 and KV, and creates the Custom Domain if wrangler.jsonc routes are enabled. Observability is already on in wrangler.jsonc."
ROUTE_PATTERN=$(wrangler_routes_pattern || true)
ROUTES_ON=$(wrangler_routes_enabled || true)
if is_loopback_host "$LAB_HOST"; then
  warn "VITE_LAB_URL is loopback. Deploy uses wrangler.jsonc (routes pattern ${ROUTE_PATTERN:-unknown})."
  if [[ "$ROUTES_ON" == true ]]; then
    warn "routes are still enabled; not deploying so the committed custom domain is not attached."
    note "skipped"
  elif confirm "Deploy now (workers.dev / disabled custom domain)?"; then
    ensure_wrangler_login
    bun run deploy || { SKIPPED+=("bun run deploy"); warn "deploy failed"; }
  else
    note "skipped. wrangler secret put needs this Worker to exist first."
  fi
elif [[ -n "$LAB_HOST" && -n "$ROUTE_PATTERN" && "$ROUTE_PATTERN" != "$LAB_HOST" ]]; then
  warn "VITE_LAB_URL host is $LAB_HOST but wrangler.jsonc routes pattern is $ROUTE_PATTERN."
  if confirm "Deploy now?"; then
    ensure_wrangler_login
    bun run deploy || { SKIPPED+=("bun run deploy"); warn "deploy failed"; }
  else
    note "skipped. wrangler secret put needs this Worker to exist first."
  fi
elif confirm "Deploy now?"; then
  ensure_wrangler_login
  bun run deploy || { SKIPPED+=("bun run deploy"); warn "deploy failed"; }
else
  note "skipped. wrangler secret put needs this Worker to exist first."
fi

# ── 21. Worker secrets ──────────────────────────────────────────────
stage "Cloudflare Worker secrets"
say "wrangler secret put of credential keys from .env.local. The Worker must already exist. Does not put LAB_DEV_* or public branding."
if confirm "Put Worker secrets now?"; then
  ensure_wrangler_login
  put_wrangler_secret BETTER_AUTH_SECRET "$(_existing BETTER_AUTH_SECRET || true)"
  put_wrangler_secret HOST_CONSOLE_TOKEN "$(_existing HOST_CONSOLE_TOKEN || true)"
  put_wrangler_secret HOSTED_APP_CLIENT_SECRET "$(_existing HOSTED_APP_CLIENT_SECRET || true)"
  put_wrangler_secret HOSTED_APP_WEBHOOK_SECRET "$(_existing HOSTED_APP_WEBHOOK_SECRET || true)"
  put_wrangler_secret HOSTED_APP_PRIVATE_KEY "$( _existing HOSTED_APP_PRIVATE_KEY | env_unescape_nl || true )"
  put_wrangler_secret CATALOG_ANTHROPIC_API_KEY "$(_existing CATALOG_ANTHROPIC_API_KEY || true)"
  put_wrangler_secret CATALOG_OPENAI_API_KEY "$(_existing CATALOG_OPENAI_API_KEY || true)"
  put_wrangler_secret CATALOG_XAI_API_KEY "$(_existing CATALOG_XAI_API_KEY || true)"
  put_wrangler_secret CATALOG_CURSOR_API_KEY "$(_existing CATALOG_CURSOR_API_KEY || true)"
  put_wrangler_secret CATALOG_ANTIGRAVITY_OAUTH "$(_existing CATALOG_ANTIGRAVITY_OAUTH || true)"
else
  note "skipped"
fi

# ── 22. Remote D1 migrations ────────────────────────────────────────
stage "Remote D1 migrations"
say "Applies apps/web/migrations to remote D1 hakasebot (vault, repo, and wake tables)."
if confirm "Run bun run db:migrate:remote?"; then
  bun run db:migrate:remote || { SKIPPED+=("db:migrate:remote"); warn "migrate failed"; }
else
  note "skipped"
fi
note "local lab: bun run dev → http://localhost:47821"

finish
